      "evidence": "Request-controlled input reaches an OS command via string concatenation. src/input.js readName(req) returns String(req.query.name || 'default'); the String() cast only coerces type and does NOT strip shell metacharacters. src/runner.js convert(req, done) does: const name = readName(req); exec('convert ' + name + ' output.pdf', done). child_process.exec runs the concatenated string through /bin/sh -c, so the shell interprets name. Verified: a request with ?name=x; id; # makes the shell run 'id', returning 'uid=... gid=... groups=...' server-side -> arbitrary command execution (RCE) as the process user. Contrast src/safe-runner.js safeConvert(name, done) which uses spawn('convert', [name, 'output.pdf'], { shell: false }, done): the array form with shell:false passes name as a single literal argv element, so metacharacters are NOT interpreted; this path is effectively protected and is NOT flagged.",
      "remediation": "In src/runner.js replace the string-building exec with the argument-array spawn form (as already done in src/safe-runner.js): const { spawn } = require('child_process'); function convert(req, done) { const name = readName(req); const child = spawn('convert', [name, 'output.pdf'], { shell: false }); child.on('error', done); child.on('close', code => done(code ? new Error('convert failed: ' + code) : null)); }. If a string command is truly required, never interpolate req-derived data; instead pass values as an argv array. Additionally enforce an allowlist/validate the name (e.g., restrict to a charset like ^[A-Za-z0-9._-]+$ and resolve/confirm the path is within an allowed input directory) so a crafted filename cannot point convert at arbitrary files."
    }
  ],
  "scanned_files": ["src/input.js", "src/runner.js", "src/safe-runner.js"],
  "source_modified": false
}
"}

